const cart = [
  { id: 1, name: 'Keyboard', price: 1500, qty: 1, inStock: true },
  { id: 2, name: 'Mouse', price: 600, qty: 2, inStock: true },
  { id: 3, name: 'Monitor', price: 9000, qty: 1, inStock: false }
];

const available = cart.filter(item => item.inStock);
const lines = available.map(item => `${item.name} x${item.qty}`);
const total = available.reduce((sum, item) => sum + item.price * item.qty, 0);
const canCheckout = available.length > 0 && cart.every(item => item.qty > 0);

console.log(lines);       // ['Keyboard x1', 'Mouse x2']
console.log(total);       // 2700
console.log(canCheckout); // true

const scores = [10, 9, 100, 1];
const sorted = scores.toSorted((a, b) => a - b);
console.log([...scores].sort());
console.log(sorted);
console.log(scores);

