const lines = stdin.trim().split('\n');
const n = parseInt(lines[0], 10);
const orders = lines.slice(1, n + 1).map(line => {
  const [id, customer, category, amount, status] = line.trim().split(/\s+/);
  return { id, customer, category, amount: Number(amount), status };
});

const delivered = orders.filter(o => o.status === 'delivered');
const revenue = delivered.reduce((sum, o) => sum + o.amount, 0);
const sumBy = key => delivered.reduce((acc, o) => {
  acc[o[key]] = (acc[o[key]] || 0) + o.amount;
  return acc;
}, {});
const rank = totals => Object.entries(totals).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
const categories = rank(sumBy('category'));
const customers = rank(sumBy('customer'));

console.log('delivered: ' + delivered.length);
console.log('revenue: ' + revenue);
console.log('by category: ' + (categories.length ? categories.map(([k, v]) => k + '=' + v).join(', ') : 'none'));
console.log('top customer: ' + (customers.length ? customers[0][0] + ' (' + customers[0][1] + ')' : 'none'));
console.log('any cancelled: ' + (orders.some(o => o.status === 'cancelled') ? 'yes' : 'no'));
